const listChannelsOrganizationsNeedingRetention = `-- name: ListChannelsOrganizationsNeedingRetention :many
WITH sweep AS (
    SELECT $4::timestamptz AS at
)
SELECT settings.organization_id,
       settings.project_id,
       settings.message_retention_days,
       settings.instance_retention_days
FROM channels_settings settings
CROSS JOIN sweep
WHERE (settings.organization_id, settings.project_id) > ($1::text, $2::uuid)
  AND (
    EXISTS (
      SELECT 1 FROM channels_messages m
      WHERE m.organization_id = settings.organization_id AND m.project_id = settings.project_id
        AND m.deleted IS FALSE
        AND m.created_at < sweep.at - make_interval(0, 0, 0, settings.message_retention_days)
    )
    OR EXISTS (
      SELECT 1 FROM channels_instances i
      WHERE i.organization_id = settings.organization_id AND i.project_id = settings.project_id
        AND i.deleted IS FALSE
        AND i.expires_at < sweep.at - make_interval(0, 0, 0, settings.instance_retention_days)
    )
  )
ORDER BY settings.organization_id, settings.project_id
LIMIT $3::int
`

type ListChannelsOrganizationsNeedingRetentionParams struct {
	AfterOrganizationID string
	AfterProjectID      uuid.UUID
	ResultLimit         int32
	Now                 pgtype.Timestamptz
}

type ListChannelsOrganizationsNeedingRetentionRow struct {
	OrganizationID        string
	ProjectID             uuid.UUID
	MessageRetentionDays  int32
	InstanceRetentionDays int32
}

// Keyset page over the organization/project scopes that actually have something to retire,
// so a sweep costs one indexed query instead of two per project that has
// ever used Channels. Both EXISTS clauses ride the (organization_id,
// created_at) and (organization_id, expires_at) indexes. The sweep time is
// bound once in a CTE: the query generator mangles a named parameter that
// appears more than once inside correlated subqueries.
func (q *Queries) ListChannelsOrganizationsNeedingRetention(ctx context.Context, arg ListChannelsOrganizationsNeedingRetentionParams) ([]ListChannelsOrganizationsNeedingRetentionRow, error) {
	rows, err := q.db.Query(ctx, listChannelsOrganizationsNeedingRetention,
		arg.AfterOrganizationID,
		arg.AfterProjectID,
		arg.ResultLimit,
		arg.Now,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListChannelsOrganizationsNeedingRetentionRow
	for rows.Next() {
		var i ListChannelsOrganizationsNeedingRetentionRow
		if err := rows.Scan(
			&i.OrganizationID,
			&i.ProjectID,
			&i.MessageRetentionDays,
			&i.InstanceRetentionDays,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

