// Atomic reclaim-or-create of this account's single browser session. The
// partial unique index makes simultaneous first sends and reloads converge on
// one row without locking the project. announce_seq is deliberately left
// untouched on reclaim: re-entering the dashboard is not a new announcement.
func (q *Queries) UpsertDashboardInstance(ctx context.Context, arg UpsertDashboardInstanceParams) (ChannelsInstance, error) {
	row := q.db.QueryRow(ctx, upsertDashboardInstance,
		arg.OrganizationID,
		arg.ProjectID,
		arg.SubjectID,
		arg.Label,
		arg.Note,
		arg.AnnounceSeq,
		arg.ExpiresAt,
		arg.ReplaceNote,
	)
	var i ChannelsInstance
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ProjectID,
		&i.SubjectID,
		&i.Label,
		&i.Note,
		&i.Origin,
		&i.ResumeHash,
		&i.AnnounceSeq,
		&i.ExpiresAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Deleted,
	)
	return i, err
}

const upsertThreadPreference = `-- name: UpsertThreadPreference :one
INSERT INTO channels_thread_preferences (organization_id, project_id, subject_id, conversation_id, followed, muted)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (organization_id, project_id, subject_id, conversation_id)
DO UPDATE SET followed = CASE WHEN $7::boolean THEN EXCLUDED.followed ELSE channels_thread_preferences.followed END,
              muted = CASE WHEN $8::boolean THEN EXCLUDED.muted ELSE channels_thread_preferences.muted END,
              updated_at = clock_timestamp()
RETURNING id, organization_id, project_id, subject_id, conversation_id, followed, muted, created_at, updated_at
`

type UpsertThreadPreferenceParams struct {
	OrganizationID string
	ProjectID      uuid.UUID
	SubjectID      string
	ConversationID uuid.UUID
	Followed       bool
	Muted          bool
	SetFollowed    bool
	SetMuted       bool
}

func (q *Queries) UpsertThreadPreference(ctx context.Context, arg UpsertThreadPreferenceParams) (ChannelsThreadPreference, error) {
	row := q.db.QueryRow(ctx, upsertThreadPreference,
		arg.OrganizationID,
		arg.ProjectID,
		arg.SubjectID,
		arg.ConversationID,
		arg.Followed,
		arg.Muted,
		arg.SetFollowed,
		arg.SetMuted,
	)
	var i ChannelsThreadPreference
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ProjectID,
		&i.SubjectID,
		&i.ConversationID,
		&i.Followed,
		&i.Muted,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
